package work.archaic.service.build.v01;

import java.lang.annotation.ElementType;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.annotation.Target;

/**
 * Container annotation for repeated {@link Repository} annotations.
 *
 * <p><strong>DO NOT USE DIRECTLY.</strong> This annotation is required by Java's
 * {@code @Repeatable} mechanism and is automatically generated by the compiler
 * when multiple {@code @Repository} annotations are applied to a module.
 *
 * <p>Users should only use {@link Repository} directly. The compiler will
 * automatically wrap multiple instances into this container annotation.
 */
@Retention(RetentionPolicy.SOURCE)
@Target(ElementType.MODULE)
public @interface Repositories {
  Repository[] value();
}
